using System;using System.Linq;
namespace GearLab {
 public static class RobotTransmission60 {
  public static bool OutputPart(Result r,CadPart p){TransmissionMotion m;if(r.Engineering!=null&&r.TransmissionMotions.TryGetValue(p.Id,out m))return Math.Abs(m.Gain-r.Engineering.SpeedGain)<1e-9&&!m.Orbit;if(r.Train!=null){var leaf=r.Train.Stages.LastOrDefault(n=>!r.Train.Stages.Any(t=>t.Parent==n.Id||t.SecondParent==n.Id));TrainMotion tm;if(leaf!=null&&p.Id.StartsWith(leaf.Id+"_")&&r.TrainMotions.TryGetValue(p.Id,out tm)){var id=p.Id.Substring(leaf.Id.Length+1);var source=new CadPart(id,p.Label,p.Role,p.Color);return OutputPart(tm.Source.Result,source)||new[]{"pairOutput","beltOutput","carrier","ring","stageCarrier","waveOutput"}.Contains(tm.Source.Kind);}}return false;}
  public static void ValidateJoint(RobotJoint j,Result r){if(!r.Valid)throw new Exception("Исправьте параметры передачи.");if(r.Engineering!=null&&r.Engineering.MultiInput)throw new Exception("Двухвходовой дифференциал требует двух приводов; один мотор сустава его не определяет.");if(r.P.Kind==12&&!j.Linear)throw new Exception("Реечная передача устанавливается в линейный шарнир.");if(j.Linear&&r.P.Kind==12&&(j.Minimum< -r.P.RackTravel/2-r.P.RackPosition||j.Maximum>r.P.RackTravel/2-r.P.RackPosition))throw new Exception("Пределы линейного шарнира должны укладываться в ход рейки.");if(j.Linear&&r.P.Kind==12&&Math.PI*r.P.Module*r.P.Teeth>100)throw new Exception("Ход рейки за оборот превышает диапазон текущего линейного контроллера (100 мм/об).");if(j.Linear&&r.P.Kind!=12&&r.P.Kind>=5)throw new Exception("Для линейного шарнира выберите рейку или существующий винтовой привод.");}
 }
}
